package main

import "fmt"

type Task struct {
	ID int
	Completed bool
}

func main() {
	tasks := []Task{{ID: 7}, {ID: 12}}
	for i := range tasks {
		if tasks[i].ID == 12 {
			tasks[i].Completed = true
			break
		}
	}
	for _, task := range tasks {
		fmt.Println(task.ID, task.Completed)
	}
}
